import { Router, type Request, type Response } from "express";
import { 
  createBoard,
  getBoard,
  listBoards,
  deleteBoard,
  createCard,
  getCardsByBoard,
  updateCardPosition,
  deleteCard
} from "../db/boards-table";

export const router = Router();

// Get all boards
router.get("/boards", (req: Request, res: Response) => {
  const boards = listBoards();
  res.json(boards);
});

// Get a specific board by ID
router.get("/boards/:id", (req: Request, res: Response) => {
  const boardId = req.params.id;
  const board = getBoard(boardId);

  if (!board) {
    return res.status(404).json({ error: "Board not found" });
  }

  res.json(board);
});

// Create a new board
router.post("/boards", (req: Request, res: Response) => {
  const { id, name } = req.body;

  if (!id || !name) {
    return res.status(400).json({ error: "ID and name are required" });
  }

  createBoard(id, name);
  res.status(201).json({ message: "Board created successfully" });
});

// Delete a board
router.delete("/boards/:id", (req: Request, res: Response) => {
  const boardId = req.params.id;

  const board = getBoard(boardId);
  if (!board) {
    return res.status(404).json({ error: "Board not found" });
  }

  deleteBoard(boardId);
  res.json({ message: "Board deleted successfully" });
});

// Get all cards for a specific board
router.get("/boards/:boardId/cards", (req: Request, res: Response) => {
  const boardId = req.params.boardId;

  const cards = getCardsByBoard(boardId);

  if (cards.length === 0) {
    return res.status(404).json({ error: "No cards found for this board" });
  }

  res.json(cards);
});

// Create a new card for a specific board
router.post("/boards/:boardId/cards", (req: Request, res: Response) => {
  const { id, title, description, column_name, position } = req.body;
  const boardId = req.params.boardId;

  if (!id || !title || !column_name || position === undefined) {
    return res.status(400).json({ error: "ID, title, column_name, and position are required" });
  }

  createCard(id, boardId, title, description, column_name, position);
  res.status(201).json({ message: "Card created successfully" });
});

// Update card position
router.put("/cards/:cardId/position", (req: Request, res: Response) => {
  const { cardId } = req.params;
  const { column_name, position } = req.body;

  if (!column_name || position === undefined) {
    return res.status(400).json({ error: "Column name and position are required" });
  }

  updateCardPosition(cardId, column_name, position);
  res.json({ message: "Card position updated successfully" });
});

// Delete a card
router.delete("/cards/:cardId", (req: Request, res: Response) => {
  const cardId = req.params.cardId;

  deleteCard(cardId);
  res.json({ message: "Card deleted successfully" });
});

