export const router = Router();

// Mock payment processing function
function processPayment(orderId: number, amount: number): Promise<void> {
  return new Promise((resolve) => {
    // Simulate payment processing
    setTimeout(() => {
      // Update order payment status
      ordersDb.exec(`UPDATE orders SET paymentStatus = 'paid' WHERE orderId = ?`, [orderId]);
      resolve();
    }, 1000);
  });
}

router.post("/charge", middleware, async (req: Request, res: Response) => {
  try {
    const { customerId, lineItems, amount } = req.body;

    if (!customerId || !lineItems || !amount) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    // Insert new order into database
    ordersDb.exec(
      "INSERT INTO orders (customerId, lineItems, paymentStatus) VALUES (?, ?, ?)",
      [customerId, lineItems, "pending"]
    );

    // Process payment
    await processPayment(ordersDb.prepare("SELECT MAX(orderId) FROM orders").get().orderId, amount);

    return res.status(201).json({ message: "Payment processed successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to process payment" });
  }
});

