import { Router, type Request, type Response } from "express";
import { Transaction, getTransactions, getTransactionById, insertTransaction } from "../db/transactions-table";

export const router = Router();

// Get all transactions
router.get("/", (req: Request, res: Response) => {
  try {
    const transactions: Transaction[] = getTransactions();
    res.json(transactions);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch transactions" });
  }
});

// Get a transaction by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);
    const transaction: Transaction | undefined = getTransactionById(id);

    if (!transaction) {
      return res.status(404).json({ error: "Transaction not found" });
    }

    res.json(transaction);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch transaction" });
  }
});

// Create a new transaction
router.post("/", (req: Request, res: Response) => {
  try {
    const { amount, merchant, date, category }: { amount: number, merchant: string, date: string, category: string } = req.body;

    if (!amount || !merchant || !date || !category) {
      return res.status(400).json({ error: "Missing required fields: amount, merchant, date, category" });
    }

    insertTransaction(amount, merchant, date, category);

    // Fetch the created transaction to send back
    const transactions: Transaction[] = getTransactions();
    const createdTransaction: Transaction | undefined = transactions.find(t => t.amount === amount && t.merchant === merchant && t.date === date && t.category === category);

    if (!createdTransaction) {
      return res.status(500).json({ error: "Failed to retrieve created transaction" });
    }

    res.status(201).json(createdTransaction);
  } catch (error) {
    res.status(500).json({ error: "Failed to create transaction" });
  }
});

// Update a transaction's category
router.put("/:id/category", (req: Request, res: Response) => {
  try {
    const id: number = Number(req.params.id);
    const { category }: { category: string } = req.body;

    if (!category) {
      return res.status(400).json({ error: "Missing required field: category" });
    }

    const transaction: Transaction | undefined = getTransactionById(id);

    if (!transaction) {
      return res.status(404).json({ error: "Transaction not found" });
    }

    // Update the category
