import { Router, type Request, type Response } from "express";
import { insertReading, getReadingsBySensor, getLatestReadingByWarehouse } from "../db/readings-table";
import { getDeviceById } from "../db/devices-table";
import { middleware } from "../middleware/device-api-key-check";

export const router = Router();

router.post("/sensor-readings", middleware, (req: Request, res: Response) => {
  const { sensorId, warehouseId, value, timestamp, apiKey } = req.body;

  // Validate required fields
  if (typeof sensorId !== "number" || typeof warehouseId !== "number" || typeof value !== "number" || typeof timestamp !== "number" || !apiKey) {
    return res.status(400).json({ error: "Invalid input data" });
  }

  // Validate device API key
  const device = getDeviceById(sensorId);
  if (!device || device.apiKeyHash !== apiKey) {
    return res.status(401).json({ error: "Invalid or missing API key" });
  }

  // Insert the reading into the database
  insertReading(sensorId, warehouseId, value, timestamp);

  // Return success response
  return res.status(201).json({ message: "Reading inserted successfully" });
});

router.get("/sensor-readings/:sensorId", (req: Request, res: Response) => {
  const sensorId = Number(req.params.sensorId);

  if (isNaN(sensorId)) {
    return res.status(400).json({ error: "Invalid sensor ID" });
  }

  const readings = getReadingsBySensor(sensorId);
  return res.json(readings);
});

router.get("/latest-reading/:warehouseId", (req: Request, res: Response) => {
  const warehouseId = Number(req.params.warehouseId);

  if (isNaN(warehouseId)) {
    return res.status(400).json({ error: "Invalid warehouse ID" });
  }

  const latestReading = getLatestReadingByWarehouse(warehouseId);
  if (!latestReading) {
    return res.status(404).json({ error: "No latest reading found" });
  }

  return res.json(latestReading);
});

import { Router, type Request, type Response } from "express";
import { getLatestReadingByWarehouse, getReadingsBySensor } from "../db/readings-table";
import { getDeviceById } from "../db/devices-table";

export const router = Router();

// Define alert thresholds
const HEARTBEAT_INTERVAL = 60000; // 1 minute
const VALUE_THRESHOLD = 10; // Example threshold

router.get("/alert", (req: Request, res: Response) => {
  const warehouseId = Number(req.query.warehouseId);
  const sensorId = Number(req.query.sensorId);

  if (!warehouseId || !sensorId) {
    return res.status(400).json({ error: "Missing required parameters" });
  }

  // Check for missed heartbeats
  const latestReading = getLatestReadingByWarehouse(warehouseId);
  if (!latestReading || Date.now() - latestReading.timestamp > HEARTBEAT_INTERVAL) {
    return res.status(200).json({ alert: "Missed heartbeat" });
  }

  // Check for out-of-range readings
  const readings = getReadingsBySensor(sensorId);
  const device = getDeviceById(sensorId);

  if (!device) {
    return res.status(200).json({ alert: "Device not found" });
  }

  const { min, max } = device;
  const values = readings.map(reading => reading.value);

  if (values.some(value => value < min || value > max)) {
    return res.status(200).json({ alert: "Out-of-range reading" });
  }

  return res.status(200).json({ alert: "No alert" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check API key for POST requests to /readings
  if (req.method !== "POST" || !req.path.startsWith("/readings")) {
    next();
    return;
  }

  const apiKey = req.headers["x-api-key"];
  const expectedApiKey = process.env.DEVICE_API_KEY;

  if (!apiKey || !expectedApiKey) {
    res.status(401).json({ error: "Invalid API key" });
    return;
  }

  // Create HMAC of the received API key
  const hmac = createHmac("sha256", expectedApiKey);
  hmac.update(apiKey as string);
  const expectedHmac = hmac.digest();

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(Buffer.from(expectedHmac), Buffer.from(apiKey as string));

  if (!isValid) {
    res.status(401).json({ error: "Invalid API key" });
    return;
  }

  next();
}

