import { Router, type Request, type Response } from "express";
import { getAllDevices, getDeviceById } from "../db/devices-table";
import { getSchedules, getScheduleById, updateSchedule } from "../db/schedules-table";

export const router = Router();

router.get("/run", (req: Request, res: Response) => {
  // Get all scheduled rules
  const schedules = getSchedules();

  // For each schedule, check if it's time to run
  const now = new Date().toISOString();
  schedules.forEach((schedule: Schedule) => {
    if (schedule.triggerTime <= now) {
      // Find the target device
      const device = getDeviceById(Number(schedule.targetDevice));
      if (device) {
        // Update the device's last known state based on the action
        if (schedule.action === "turnOn") {
          device.lastKnownState = "on";
        } else if (schedule.action === "turnOff") {
          device.lastKnownState = "off";
        }

        // Mark this schedule as completed by updating it
        updateSchedule(schedule.id, schedule.triggerTime, schedule.targetDevice, schedule.action);
      }
    }
  });

  res.status(200).json({ message: "Scheduled rules processed" });
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to device control routes
  if (!req.path.startsWith("/devices") || req.method !== "POST") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  const expectedToken = createHmac("sha256", secret)
    .update("owner-token")
    .digest("hex");

  const tokenBuffer = Buffer.from(token);
  const expectedBuffer = Buffer.from(expectedToken);

  try {
    if (timingSafeEqual(tokenBuffer, expectedBuffer)) {
      next();
    } else {
      res.status(401).json({ error: "Unauthorized" });
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
  }
}

