import { Router, type Request, type Response } from "express";
import { middleware } from "../middleware/reason-required-guard";
import { getClaimById, updateClaimStatus } from "../db/claims-table";
import { insertClaimDecision } from "../db/claim-decisions-table";

export const router = Router();

router.post("/decide", middleware, (req: Request, res: Response) => {
  const { claimId, decision, reasonText, adjusterId } = req.body;

  // Validate required fields
  if (!claimId || !decision || !reasonText || !adjusterId) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  // Validate decision value
  if (decision !== "approve" && decision !== "deny") {
    return res.status(400).json({ error: "Invalid decision value" });
  }

  // Get claim by ID
  const claim = getClaimById(Number(claimId));
  if (!claim) {
    return res.status(404).json({ error: "Claim not found" });
  }

  // Insert claim decision
  insertClaimDecision(
    Number(adjusterId),
    decision,
    reasonText,
    Number(claimId)
  );

  // Update claim status based on decision
  if (decision === "approve") {
    updateClaimStatus(Number(claimId), "approved");
  } else {
    updateClaimStatus(Number(claimId), "denied");
  }

  return res.status(201).json({ message: "Decision recorded successfully" });
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to POST requests to the /claims/:id/decide endpoint
  if (req.method !== "POST" || !req.path.match(/^\/claims\/[^\/]+\/decide$/)) {
    next();
    return;
  }

  // Check if reason is provided in the request body
  const reason = req.body.reason;

  if (!reason || reason.trim() === "") {
    res.status(400).json({ error: "A reason is required for finalising a claim decision." });
    return;
  }

  next();
}

