// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  const { partySize, timeSlot, tableAssignment, guestContactInfo } = req.body;

  if (!partySize || !timeSlot || !tableAssignment || !guestContactInfo) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  insertReservation(partySize, timeSlot, tableAssignment, guestContactInfo);

  // Fetch the created reservation to send back
  const createdReservation = getReservations().find(r => r.partySize === partySize && r.timeSlot === timeSlot);

  if (!createdReservation) {
    return res.status(500).json({ error: "Failed to create reservation" });
  }

  res.status(201).json(createdReservation);
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { partySize, timeSlot, tableAssignment, guestContactInfo } = req.body;

  if (!partySize || !timeSlot || !tableAssignment || !guestContactInfo) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingReservation = getReservationById(id);

  if (!existingReservation) {
    return res.status(404).json({ error: "Reservation not found" });
  }

  updateReservation(id, partySize, timeSlot, tableAssignment, guestContactInfo);

  // Fetch the updated reservation to send back
  const updatedReservation = getReservationById(id);

  if (!updatedReservation) {
    return res.status(500).json({ error: "Failed to update reservation" });
  }

  res.json(updatedReservation);
});

// Delete a reservation
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  const existingReservation = getReservationById(id);

  if (!existingReservation) {
    return res.status(404).json({ error: "Reservation not found" });
  }

  deleteReservation(id);

  res.json({ message: "Reservation deleted successfully" });
});

// Check table availability for a time slot
router.get("/availability", (req: Request, res: Response) => {
  const { timeSlot } = req.query;

  if (!timeSlot || typeof timeSlot !== "string") {
    return res.status(400).json({ error: "Time slot query parameter is required" });
  }

  const reservations = getReservations();
  const availableTables = ["table1", "table2", "table3", "table4", "table5"];

  const occupiedTables = reservations.filter(r => r.timeSlot === timeSlot).map(r => r.tableAssignment);

  const available = availableTables.filter(table => !occupiedTables.includes(table));

  res.json({ availableTables: available });
});

