import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to POST requests to /expenses/approve or /expenses/reject
  if (!(req.method === "POST" && (req.path === "/expenses/approve" || req.path === "/expenses/reject"))) {
    next();
    return;
  }

  // Check if user is manager
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Create expected signature
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64");

  // Use timingSafeEqual to prevent timing attacks
  const signatureBuffer = Buffer.from(signature, "base64");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64");

  if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // For now, we'll just pass through - actual implementation
  // would check user roles and direct reports
  next();
}

