import { Router, type Request, type Response } from "express";
import { insertClockEvent, getClockEventsByEmployeeId } from "../db/clock-events-table";

export const router = Router();

// POST /timesheets - Record a clock event
router.post("/timesheets", (req: Request, res: Response) => {
  const { employeeId, eventType, timestamp } = req.body;

  if (typeof employeeId !== "number" || typeof eventType !== "string" || typeof timestamp !== "string") {
    return res.status(400).json({ error: "Invalid input data" });
  }

  if (eventType !== "in" && eventType !== "out") {
    return res.status(400).json({ error: "Invalid eventType. Must be 'in' or 'out'" });
  }

  insertClockEvent(employeeId, eventType);
  return res.status(201).json({ message: "Clock event recorded successfully" });
});

// GET /timesheets/:employeeId - Get all clock events for an employee
router.get("/timesheets/:employeeId", (req: Request, res: Response) => {
  const employeeId = Number(req.params.employeeId);

  if (isNaN(employeeId)) {
    return res.status(400).json({ error: "Invalid employeeId" });
  }

  const clockEvents = getClockEventsByEmployeeId(employeeId);
  return res.json(clockEvents);
});

// GET /timesheets/weekly-summary/:employeeId - Get weekly summary of hours for an employee
router.get("/timesheets/weekly-summary/:employeeId", (req: Request, res: Response) => {
  const employeeId = Number(req.params.employeeId);

  if (isNaN(employeeId)) {
    return res.status(400).json({ error: "Invalid employeeId" });
  }

  const clockEvents = getClockEventsByEmployeeId(employeeId);

  // Filter events to only include 'in' and 'out' events
  const inEvents = clockEvents.filter(event => event.eventType === "in");
  const outEvents = clockEvents.filter(event => event.eventType === "out");

  // Calculate total hours
  let totalHours = 0;
  for (let i = 0; i < inEvents.length; i++) {
    if (i < outEvents.length) {
      const inTime = new Date(inEvents[i].timestamp);
      const outTime = new Date(outEvents[i].timestamp);
      const duration = outTime.getTime() - inTime.getTime();
      totalHours += duration / (1000 * 60 * 60); // Convert milliseconds to hours
    }
  }

  return res.json({ totalHours });
});

import { Router, type Request, type Response } from "express";
import { getClockEventsByEmployeeId } from "../db/clock-events-table";
import { middleware } from "../middleware/approved-only-payroll-guard";

export const router = Router();

router.get('/payroll', middleware, (req: Request, res: Response) => {
  // Extract employee ID from request query
  const employeeId = Number(req.query.employeeId);

  // Validate employeeId is a number
  if (isNaN(employeeId)) {
    return res.status(400).json({ error: 'Invalid employee ID' });
  }

  // Get clock events for the specified employee
  const clockEvents = getClockEventsByEmployeeId(employeeId);

  // Filter approved timesheets (assuming 'in' and 'out' events are approved)
  const approvedEvents = clockEvents.filter(event => event.eventType === 'in' || event.eventType === 'out');

  // Generate payroll file content
  let payrollContent = 'Employee ID,Event Type,Timestamp\n';
  approvedEvents.forEach(event => {
    payrollContent += `${event.employeeId},${event.eventType},${event.timestamp}\n`;
  });

  // Send the payroll file content as CSV
  res.setHeader('Content-Type', 'text/csv');
  res.setHeader('Content-Disposition', 'attachment; filename=payroll.csv');
  res.status(200).send(payrollContent);
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to POST requests to the payroll export endpoint
  if (req.method !== "POST" || !req.path.startsWith("/payroll/export")) {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const token = req.headers["authorization"]?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "Authorization token required" });
    return;
  }

  try {
    const [payload, signature] = token.split(".");

    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64");

    const signatureBuffer = Buffer.from(signature, "base64");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Token is valid, proceed
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}

